import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import extractText from 'flarum/common/utils/extractText';
import { resources } from '../depot-api';
import { t } from './bits';
/** Point a file at an existing discussion as its support discussion, or unlink it. */
export default class LinkDiscussionModal extends FormModal {
  oninit(vnode) {
    super.oninit(vnode);
    const d = this.attrs.file.discussion;
    this.value = d ? d.url : '';
  }
  className() {
    return 'DepotLinkModal Modal--small';
  }
  title() {
    return t('link.title');
  }
  content() {
    const linked = !!this.attrs.file.discussion;
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form-group"
    }, m("label", {
      for: "depot-link"
    }, t('link.label')), m("input", {
      id: "depot-link",
      className: "FormControl",
      value: this.value,
      oninput: e => this.value = e.target.value,
      placeholder: extractText(t('link.placeholder'))
    }), m("p", {
      className: "helpText"
    }, t('link.help'))), m(Button, {
      className: "Button Button--primary Button--block",
      type: "submit",
      loading: this.loading,
      disabled: !this.value.trim()
    }, t('link.save')), linked ? m(Button, {
      className: "Button Button--block",
      type: "button",
      onclick: () => this.save(''),
      disabled: this.loading
    }, t('link.unlink')) : null);
  }
  onsubmit(e) {
    e.preventDefault();
    this.save(this.value);
  }
  save(value) {
    this.loading = true;
    resources.update('depot-files', this.attrs.file.id, {
      linkDiscussion: value.trim()
    }).then(() => {
      this.hide();
      this.attrs.onsave();
    }).catch(() => {
      /* app.request already showed the alert; the modal stays open to try again */
    }).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-depot', 'forum/components/LinkDiscussionModal', LinkDiscussionModal);