import extractText from 'flarum/common/utils/extractText';
import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { state, compact, copyText, toggleWatch, showFile, resources } from '../depot-api';
import { t } from './bits';
import DownloadModal, { startDownload } from './DownloadModal';
import { changes, hasChanges } from './file/shared';
import { hero, controls } from './file/Hero';
import { overview, more } from './file/Overview';
import { versions } from './file/Versions';
import { reviews, reviewItem, replyEditor } from './file/Reviews';
import { discussion } from './file/Discussion';
import { side } from './file/Sidebar';
import { offer, downloadCard } from './file/DownloadCard';
import { productCard, installCard } from './file/ProductCard';
const TABS = ['overview', 'versions', 'reviews', 'discussion'];
/**
 * One file. Laid out like a discussion — hero across the top, content on the
 * left, a sidebar on the right — so it reads as part of the forum. The sidebar
 * holds everything needed to decide and download without scrolling.
 *
 * The pieces are drawn by the helpers in ./file; the methods here stay so each
 * piece can still be reached (and extended) on the page.
 */
export default class FilePage extends Page {
  tab = 'overview';
  starFilter = 0;
  open = {};
  file = null;
  missing = false;
  replying = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.tab = 'overview';
    this.starFilter = 0;
    this.open = {
      0: true
    };
    this.file = null;
    this.missing = false;
    this.replying = null;
    this.load();
  }
  load() {
    // A linked discussion may have changed: its posts load again when the tab is drawn.
    this.posts = undefined;
    return showFile(m.route.param('slug')).then(file => {
      state.categories = file.categories;
      // Shared so Waymark's trail can name the file and its categories.
      state.file = file;
      this.file = file;
      m.redraw();
    }, () => {
      this.missing = true;
      m.redraw();
    });
  }
  view() {
    const file = this.file;
    if (!file) {
      return m(PageStructure, {
        className: "DepotFilePage"
      }, this.missing ? this.notFound() : m(LoadingIndicator, {
        display: "block"
      }));
    }
    app.setTitle(file.title);
    app.setTitleCount(0);
    return m(PageStructure, {
      className: "DepotFilePage",
      hero: () => this.hero(file)
    }, this.pending(file), m("div", {
      className: "DepotFile"
    }, m("div", {
      className: "DepotFile-main"
    }, this.tabs(file), m("div", {
      className: "DepotFile-panel",
      role: "tabpanel"
    }, this[this.tab](file))), m("aside", {
      className: "DepotFile-side"
    }, this.side(file))));
  }

  /** The awaiting-approval notice, with Approve for a moderator. */
  pending(file) {
    if (file.approved) return null;
    return m("div", {
      className: "DepotNotice"
    }, m(Icon, {
      name: "fas fa-hourglass-half"
    }), m("span", null, t('file.pending')), file.canModerate ? m(Button, {
      className: "Button Button--small Button--primary",
      onclick: () => this.act({
        isApproved: true
      })
    }, t('file.approve')) : null);
  }
  tabs(file) {
    return m("nav", {
      className: "DepotTabs",
      role: "tablist"
    }, TABS.map(tab => m("button", {
      type: "button",
      role: "tab",
      "aria-selected": this.tab === tab ? 'true' : 'false',
      className: this.tab === tab ? 'is-active' : '',
      onclick: () => this.tab = tab
    }, t(`file.tab_${tab}`), this.tabCount(file, tab))));
  }

  /** The uploader may sell their own upload through Kiosk Sellers (Kiosk decides who may sell). */
  sellsOwn(file) {
    const me = app.session.user;
    return !!(me && app.forum.attribute('kioskCanSell') && app.routes['kiosk.selling'] && file.user && String(file.user.id) === me.id() && file.source === 'upload' && file.approved);
  }

  /** Change the file (approve, feature, sell) and show it again. */
  act(attributes) {
    return resources.update('depot-files', this.file.id, attributes).then(() => this.load());
  }
  tabCount(file, tab) {
    const n = {
      versions: file.versions.length,
      reviews: file.ratings,
      discussion: file.discussion && file.discussion.replies
    }[tab];
    return n ? m("span", {
      className: "DepotTabs-count"
    }, compact(n)) : null;
  }
  notFound() {
    return m("div", {
      className: "container DepotEmpty"
    }, m(Icon, {
      name: "fas fa-box-open"
    }), m("h3", null, t('file.missing_title')), m("a", {
      className: "Button",
      href: app.route('depot.index')
    }, t('file.missing_back')));
  }
  hero(file) {
    return hero(this, file);
  }
  controls(file) {
    return controls(this, file);
  }
  remove(file) {
    // The same confirm Flarum itself uses before deleting a discussion.
    if (!confirm(extractText(t('file.delete_confirm', {
      title: file.title
    })))) return;
    resources.remove('depot-files', file.id).then(() => m.route.set(app.route('depot.index')), () => {
      /* Flarum has shown the error; the file stays on screen. */
    });
  }

  // ---------------------------------------------------------------- overview

  overview(file) {
    return overview(this, file);
  }
  hasChanges(v) {
    return hasChanges(v);
  }
  more(file) {
    return more(file);
  }
  changes(v) {
    return changes(v);
  }

  // ---------------------------------------------------------------- versions

  versions(file) {
    return versions(this, file);
  }
  removeVersion(v) {
    if (!confirm(extractText(t('file.delete_version_confirm', {
      version: v.version
    })))) return;
    resources.remove('depot-versions', v.id).then(() => this.load(), () => {
      /* Flarum has shown the error; the version stays listed. */
    });
  }
  download(file, v) {
    startDownload(v);
    app.modal.show(DownloadModal, {
      file,
      version: v,
      onwatch: r => Object.assign(file, r)
    });
  }

  // ---------------------------------------------------------------- reviews

  reviews(file) {
    return reviews(this, file);
  }
  reviewItem(file, r) {
    return reviewItem(this, file, r);
  }
  replyEditor(r) {
    return replyEditor(this, r);
  }
  helpful(r) {
    resources.update('depot-reviews', r.id, {
      isHelpful: !r.helpfulByMe
    }).then(res => {
      r.helpful = res.helpful;
      r.helpfulByMe = res.helpfulByMe;
      m.redraw();
    }, () => {
      /* Flarum has shown the error; nothing changed here before the answer. */
    });
  }
  removeReview(r) {
    if (!confirm(extractText(t('file.delete_review_confirm')))) return;
    resources.remove('depot-reviews', r.id).then(() => this.load(), () => {
      /* Flarum has shown the error; the review stays listed. */
    });
  }

  // ---------------------------------------------------------------- discussion

  discussion(file) {
    return discussion(this, file);
  }

  /** The latest few posts through Flarum's own API, so permissions, hidden posts and formatting are core's. */
  loadPosts(d) {
    this.posts = 'loading';
    app.store.find('posts', {
      filter: {
        discussion: String(d.id),
        type: 'comment'
      },
      sort: '-createdAt',
      page: {
        limit: 4
      }
    }).then(posts => {
      this.posts = [...posts].reverse();
      m.redraw();
    }, () => {
      this.posts = [];
      m.redraw();
    });
  }

  // ---------------------------------------------------------------- sidebar

  side(file) {
    return side(this, file);
  }
  offer(file) {
    return offer(file);
  }
  downloadCard(file, v) {
    return downloadCard(this, file, v);
  }
  productCard(file) {
    return productCard(this, file);
  }
  installCard(file) {
    return installCard(this, file);
  }
  watch(file) {
    toggleWatch(file);
  }
  copy(text, id) {
    if (id === void 0) {
      id = true;
    }
    copyText(text, () => {
      this.copied = id;
      m.redraw();
      setTimeout(() => (this.copied = false, m.redraw()), 1800);
    });
  }
}
flarum.reg.add('ernestdefoe-depot', 'forum/components/FilePage', FilePage);