import app from 'flarum/forum/app';
import { flatten, resources } from '../common/jsonapi';
/*
 * Depot's API, and the little state the pages share.
 *
 * Files, reviews, versions and screenshots are JSON:API resources
 * (`resources`, read back into the shapes in types.ts). `api` is for the
 * few endpoints that are not: the multipart uploads.
 */
const url = path => `${app.forum.attribute('apiUrl')}/depot/${path}`;
export const api = {
  get: (path, params) => app.request({
    method: 'GET',
    url: url(path),
    params
  }),
  post: (path, body) => app.request({
    method: 'POST',
    url: url(path),
    body
  }),
  del: path => app.request({
    method: 'DELETE',
    url: url(path)
  }),
  // Multipart: Flarum must not try to JSON-encode the body.
  upload: (path, form, onprogress) => app.request({
    method: 'POST',
    url: url(path),
    body: form,
    serialize: raw => raw,
    config: xhr => onprogress && xhr.upload.addEventListener('progress', e => e.lengthComputable && onprogress(e.loaded / e.total))
  })
};
export { resources };
const SORTS = {
  downloads: '-downloadCount',
  rating: '-rating',
  newest: '-createdAt'
};

/** One page of the downloads list, with what the page needs beside it (the list's meta). */
export function browse(params) {
  const filter = {};
  if (params.category) filter.category = params.category;
  if (params.q) filter.q = params.q;
  if (params.compat) filter.compat = params.compat;
  if (params.filter) filter[params.filter] = '1';
  const query = {
    filter,
    page: {
      offset: params.page * PER_PAGE
    }
  };
  if (SORTS[params.sort]) query.sort = SORTS[params.sort];
  return resources.get('depot-files', query).then(doc => ({
    ...doc.meta,
    files: doc.data.map(r => flatten(r)),
    hasMore: !!doc.links?.next,
    page: params.page
  }));
}

/** The files a page of the list holds (FileResource::PER_PAGE). */
const PER_PAGE = 24;

/** A file's whole page, with the categories for its breadcrumbs. */
export const showFile = slug => resources.get(`depot-files/${encodeURIComponent(slug)}`).then(doc => ({
  ...flatten(doc.data),
  categories: doc.meta?.categories || []
}));

/** Watch or stop watching a file, from any of the places that offer it. */
export const toggleWatch = file => resources.update('depot-files', file.id, {
  isWatching: !file.watching
}).then(r => {
  file.watching = r.watching;
  file.watchers = r.watchers;
  m.redraw();
  return r;
});

/** Copy text, then call `done` (to show a tick). */
export function copyText(text, done) {
  if (!navigator.clipboard) return;
  navigator.clipboard.writeText(text).then(done, () => {
    /* The browser refused the clipboard: the text stays on screen to copy by hand. */
  });
}

/** Categories, as last sent by the server. Every page response carries them. */
export const state = {
  categories: [],
  file: null
};
export const category = slug => state.categories.find(c => c.slug === slug);
export const rootOf = c => c && c.parent ? category(c.parent) : c;
export const childrenOf = slug => state.categories.filter(c => c.parent === slug);
export const roots = () => state.categories.filter(c => !c.parent);

// --- formatting -------------------------------------------------------------

export function bytes(n) {
  if (!n) return '';
  const u = ['B', 'KB', 'MB', 'GB'];
  let i = 0;
  while (n >= 1024 && i < u.length - 1) {
    n /= 1024;
    i++;
  }
  return `${n >= 10 || i === 0 ? Math.round(n) : n.toFixed(1)} ${u[i]}`;
}
export const number = n => Number(n || 0).toLocaleString();
export function compact(n) {
  const v = Number(n || 0);
  if (v < 1000) return String(v);
  return (v / 1000).toFixed(v < 10000 ? 1 : 0).replace(/\.0$/, '') + 'k';
}
export const daysAgo = iso => iso ? Math.floor((Date.now() - new Date(iso).getTime()) / 86400000) : Infinity;

/** "$4.00" in the viewer's own locale, from cents and an ISO currency. */
export function money(cents, currency) {
  try {
    return new Intl.NumberFormat(undefined, {
      style: 'currency',
      currency: currency || 'USD',
      minimumFractionDigits: cents % 100 ? 2 : 0
    }).format(cents / 100);
  } catch (e) {
    // An unknown currency code throws: show the plain amount and the code instead.
    return `${(cents / 100).toFixed(2)} ${currency}`;
  }
}

/** The cheapest tier, for a card's price. */
export const cheapest = tiers => (tiers || []).reduce((low, t) => !low || t.cents < low.cents ? t : low, null);