import app from 'flarum/common/app';

/*
 * Depot's resources, read back into the plain shapes its pages draw: a
 * resource's attributes with its number as `id`.
 */

export const flatten = resource => ({
  id: Number(resource.id),
  ...resource.attributes
});
const url = path => `${app.forum.attribute('apiUrl')}/${path}`;
export const resources = {
  get: (path, params) => app.request({
    method: 'GET',
    url: url(path),
    params
  }),
  create: (type, attributes) => app.request({
    method: 'POST',
    url: url(type),
    body: {
      data: {
        type,
        attributes
      }
    }
  }).then(doc => flatten(doc.data)),
  update: (type, id, attributes) => app.request({
    method: 'PATCH',
    url: url(`${type}/${id}`),
    body: {
      data: {
        type,
        id: String(id),
        attributes
      }
    }
  }).then(doc => flatten(doc.data)),
  remove: (type, id) => app.request({
    method: 'DELETE',
    url: url(`${type}/${id}`)
  })
};
flarum.reg.add('ernestdefoe-depot', 'common/jsonapi', { flatten: flatten,resources: resources, });