import { state, rootOf } from '../../depot-api';
import { t } from '../bits';

/*
 * Form pieces the upload and edit forms share, so both draw a field the same way.
 */

/** The text in the input, textarea or select an event came from. */
export const valueOf = e => e.target.value;

/** A labelled input, or a textarea when `rows` is given, with optional help below. */
export function field(id, label, value, set, attrs, help) {
  if (attrs === void 0) {
    attrs = {};
  }
  const control = attrs.rows ? m("textarea", Object.assign({
    id: id,
    className: "FormControl",
    value: value,
    oninput: e => set(valueOf(e))
  }, attrs)) : m("input", Object.assign({
    id: id,
    className: "FormControl",
    value: value,
    oninput: e => set(valueOf(e))
  }, attrs));
  return m("div", {
    className: "Form-group"
  }, m("label", {
    for: id
  }, label), control, help ? m("p", {
    className: "helpText"
  }, help) : null);
}

/** Categories a file can go in: open ones without subcategories of their own. */
export function leafCategories() {
  const categories = state.categories;
  return categories.filter(c => c.open && !categories.some(s => s.parent === c.slug));
}

/** The category picker: subcategories read "Parent › Child". */
export function categorySelect(id, value, set) {
  return m("div", {
    className: "Form-group"
  }, m("label", {
    for: id
  }, t('upload.category_label')), m("select", {
    id: id,
    className: "FormControl",
    value: value,
    onchange: e => set(valueOf(e))
  }, leafCategories().map(c => m("option", {
    value: c.slug
  }, c.parent && rootOf(c) ? `${rootOf(c).name} › ${c.name}` : c.name))));
}
flarum.reg.add('ernestdefoe-depot', 'forum/components/form/fields', { valueOf: valueOf,field: field,leafCategories: leafCategories,categorySelect: categorySelect, });