import Icon from 'flarum/common/components/Icon';
import { number } from '../../depot-api';
import { t, price } from '../bits';
import { copyButton, watchButton } from './shared';

/** For someone who owns the product: how to install it, and where to manage the licence. */
function owned(page, access) {
  return [m("div", {
    className: "DepotOwned"
  }, m(Icon, {
    name: "fas fa-check-circle"
  }), " ", t('file.owned')), ...(access.install || []).map((line, i) => m("div", {
    className: "Depot-copy Depot-copy--small"
  }, m("code", null, line), copyButton(page, line, `i${i}`))), access.manageUrl ? m("a", {
    className: "Button",
    href: access.manageUrl
  }, t('file.manage_licence')) : null];
}

/** For everyone else: the prices and a way to buy. */
function buy(file) {
  return [m("h4", {
    className: "DepotSideCard-label"
  }, t('file.get_it')), m("ul", {
    className: "DepotTiers"
  }, (file.tiers || []).map(tier => m("li", null, m("span", null, tier.name), m("b", null, price(tier))))), file.buyUrl ? m("a", {
    className: "Button Button--primary Button--large DepotBuy",
    href: file.buyUrl
  }, m(Icon, {
    name: "fas fa-tag"
  }), " ", t('file.buy')) : null];
}

/**
 * A store's product: its prices and a way to buy it, or — for someone who
 * already owns it — how to install it, in the store's own words.
 */
export function productCard(page, file) {
  const access = file.access || {};
  return m("div", {
    className: "DepotSideCard DepotSideCard--download DepotSideCard--product"
  }, access.owned ? owned(page, access) : buy(file), watchButton(page, file));
}

/**
 * A GitHub-linked file is not downloaded from the forum. A Composer package
 * shows the install command (its count is Packagist's installs); anything
 * else links to its releases on GitHub.
 */
export function installCard(page, file) {
  const command = file.package ? `composer require ${file.package}` : null;
  return m("div", {
    className: "DepotSideCard DepotSideCard--download DepotSideCard--install"
  }, command ? [m("h4", {
    className: "DepotSideCard-label"
  }, t('file.install_with_composer')), m("div", {
    className: "Depot-copy"
  }, m("code", null, command), copyButton(page, command, 'install'))] : null, m("a", {
    className: `Button Button--large ${command ? '' : 'Button--primary'} DepotGitHubButton`,
    href: `https://github.com/${file.repo}`,
    target: "_blank",
    rel: "noopener noreferrer"
  }, m(Icon, {
    name: "fab fa-github"
  }), " ", t('file.view_on_github')), watchButton(page, file), m("div", {
    className: "DepotSideCard-trust"
  }, file.package ? m("span", null, m(Icon, {
    name: "fas fa-box"
  }), " ", t('file.counted_by_packagist')) : m("span", null), m("span", null, m(Icon, {
    name: "far fa-eye"
  }), " ", t('file.watchers', {
    count: number(file.watchers)
  }))));
}
flarum.reg.add('ernestdefoe-depot', 'forum/components/file/ProductCard', { productCard: productCard,installCard: installCard, });